7: import { useCatchCallback } from '../reactHelper';
8: import { findFonts, toMapCoordinates } from './core/mapUtil';
9: 
10: const onMouseEnter = () => (map.getCanvas().style.cursor = 'pointer');
11: const onMouseLeave = () => (map.getCanvas().style.cursor = '');
12: 
13: const MapMarkers = ({ markers, showTitles, cluster, direction, onClick, disabled }) => {
14:   const theme = useTheme();
15:   const desktop = useMediaQuery(theme.breakpoints.up('md'));
16:   const iconScale = useAttributePreference('iconScale', desktop ? 0.75 : 1);
17: 
18:   const disabledRef = useRef(disabled);
19:   disabledRef.current = disabled;
20: 
21:   const onMarkerClick = useCallback(
22:     (event) => {
23:       if (disabledRef.current) return;
24:       event.preventDefault();
25:       onClick?.(event.features[0].properties);
26:     },
27:     [onClick],
28:   );
29: 
30:   const onClusterClick = useCatchCallback(async (event) => {
31:     if (disabledRef.current) return;
32:     event.preventDefault();
33:     const feature = event.features[0];
34:     const zoom = await map
35:       .getSource(feature.source)
36:       .getClusterExpansionZoom(feature.properties.cluster_id);
37:     map.easeTo({ center: feature.geometry.coordinates, zoom });
38:   }, []);
39: 
40:   const layers = [
41:     {
42:       type: 'symbol',
43:       filter: ['!has', 'point_count'],
44:       layout: showTitles
45:         ? {
46:             'icon-image': '{image}',
47:             'icon-size': iconScale,
48:             'icon-allow-overlap': true,
49:             'text-field': '{title}',
50:             'text-allow-overlap': true,
51:             'text-anchor': 'bottom',
52:             'text-offset': [0, -2 * iconScale],
53:             'text-font': findFonts(map),
54:             'text-size': 12,
55:             'symbol-sort-key': ['get', 'id'],
56:           }
57:         : {
58:             'icon-image': '{image}',
59:             'icon-size': iconScale,
60:             'icon-allow-overlap': true,
61:             'symbol-sort-key': ['get', 'id'],
62:           },
63:       ...(showTitles ? { paint: { 'text-halo-color': 'white', 'text-halo-width': 1 } } : {}),
64:       ...(onClick
65:         ? { on: { mouseenter: onMouseEnter, mouseleave: onMouseLeave, click: onMarkerClick } }
66:         : {}),
67:     },
68:   ];
69: 
70:   if (direction) {
71:     layers.push({
72:       key: 'direction',
73:       type: 'symbol',
74:       filter: ['all', ['!has', 'point_count'], ['==', 'direction', true]],
75:       layout: {
76:         'icon-image': 'direction',
77:         'icon-size': iconScale,
78:         'icon-allow-overlap': true,
79:         'icon-rotate': ['get', 'rotation'],
80:         'icon-rotation-alignment': 'map',
81:       },
82:     });
83:   }
84: 
85:   if (cluster) {
86:     layers.push({
87:       key: 'clusters',
88:       type: 'symbol',
89:       filter: ['has', 'point_count'],
90:       layout: {
91:         'icon-image': 'background',
92:         'icon-size': iconScale,
93:         'icon-allow-overlap': true,
94:         'text-field': '{point_count_abbreviated}',
95:         'text-font': findFonts(map),
96:         'text-size': 14,
97:         'text-allow-overlap': true,
98:       },
99:       on: { mouseenter: onMouseEnter, mouseleave: onMouseLeave, click: onClusterClick },
100:     });
101:   }
102: 
103:   useMapLayer({
104:     source: cluster ? { cluster: true, clusterMaxZoom: 14, clusterRadius: 50 } : undefined,
105:     layers,
106:     layersDeps: [showTitles, cluster, direction, iconScale, onMarkerClick, onClusterClick],
107:     data: {
108:       type: 'FeatureCollection',
109:       features: markers.map(
110:         ({ latitude, longitude, image, title, rotation, direction: showDirection, ...rest }) => ({
111:           type: 'Feature',
112:           geometry: {
113:             type: 'Point',
114:             coordinates: toMapCoordinates(longitude, latitude),
115:           },
116:           properties: {
117:             ...rest,
118:             image: image || 'default-neutral',
119:             title: title || '',
120:             rotation: rotation || 0,
121:             direction: showDirection || false,
122:           },
123:         }),
124:       ),
125:     },
126:     dataDeps: [markers, showTitles],
127:   });
128: 
129:   return null;
130: };
131: 
132: export default MapMarkers;
