            description,
            calendarId,
            attributes: {},
          },
        );
        break;
      case 'json':
      default:
        showReport();
        break;
    }
  };

  return (
    <div className={classes.filter}>
      {deviceType !== 'none' && (
        <div className={classes.filterItem}>
          <SelectField
            label={t(deviceType === 'multiple' ? 'deviceTitle' : 'reportDevice')}
            data={
              deviceType === 'multiple' ? deviceList : deviceList.filter((it) => it.id !== 'all')
            }
            value={deviceType === 'multiple' ? deviceIds : deviceIds.find(() => true)}
            allValue="all"
            onChange={(e) => {
              const values =
                deviceType === 'multiple' ? e.target.value : [e.target.value].filter((id) => id);
              updateReportParams(searchParams, setSearchParams, 'deviceId', values);
            }}
            multiple={deviceType === 'multiple'}
            singleLine={deviceType === 'multiple'}
            fullWidth
          />
        </div>
      )}
      {deviceType === 'multiple' && (
        <div className={classes.filterItem}>
          <SelectField
            label={t('settingsGroups')}
            data={groupList}
            value={groupIds}
            onChange={(e) => {
              const values = e.target.value;
              updateReportParams(searchParams, setSearchParams, 'groupId', values);
            }}
            multiple
            singleLine
            fullWidth
          />
        </div>
      )}
      {selectedOption !== 'schedule' ? (
        <>
          <div className={classes.filterItem} style={{ flexBasis: 220 }}>
            <FormControl fullWidth>
              <InputLabel shrink>{t('reportPeriod')}</InputLabel>
              <Select
                label={t('reportPeriod')}
                value=""
                displayEmpty
                renderValue={() => periodLabel}
                onChange={(e) => {
                  setPeriod(e.target.value);
                  if (e.target.value !== 'custom') {
                    setRange(getPeriodRange(e.target.value));
                  }
                }}
                startAdornment={
                  <InputAdornment position="start">
                    <IconButton
                      edge="start"
                      size="small"
                      disabled={loading || !validRange}
                      onClick={() => shiftPeriod(-1)}
                    >
                      <ChevronLeftIcon />
                    </IconButton>
                  </InputAdornment>
                }
                endAdornment={
                  <InputAdornment position="end">
                    <IconButton
                      edge="end"
                      size="small"
                      disabled={loading || !validRange}
                      onClick={() => shiftPeriod(1)}
                    >
                      <ChevronRightIcon />
                    </IconButton>
                  </InputAdornment>
                }
              >
                <MenuItem value="day">{t('reportToday')}</MenuItem>
                <MenuItem value="week">{t('reportThisWeek')}</MenuItem>
                <MenuItem value="month">{t('reportThisMonth')}</MenuItem>
                <MenuItem value="custom">{t('reportCustom')}</MenuItem>
              </Select>
            </FormControl>
          </div>
          {period === 'custom' && (
            <div className={classes.filterItem}>
              <TextField
                label={t('reportFrom')}
                type="datetime-local"
                value={range[0] ? selectedFrom.locale('en').format('YYYY-MM-DDTHH:mm') : ''}
                onChange={(e) => setRange([e.target.value, range[1]])}
                fullWidth
              />
            </div>
          )}
          {period === 'custom' && (
            <div className={classes.filterItem}>
              <TextField
                label={t('reportTo')}
                type="datetime-local"
                value={range[1] ? selectedTo.locale('en').format('YYYY-MM-DDTHH:mm') : ''}
                onChange={(e) => setRange([range[0], e.target.value])}
                fullWidth
              />
            </div>
          )}
        </>
      ) : (
        <>
          <div className={classes.filterItem}>
            <TextField
              value={description || ''}
              onChange={(event) => setDescription(event.target.value)}
              label={t('sharedDescription')}
              fullWidth
            />
          </div>
          <div className={classes.filterItem}>
            <SelectField
              value={calendarId}
              onChange={(event) => setCalendarId(Number(event.target.value))}
              endpoint="/api/calendars"
              label={t('sharedCalendar')}
              fullWidth
            />
          </div>
        </>
      )}
      {children}
      <div className={classes.filterItem}>
        {Object.keys(options).length === 1 ? (
          <Button
            fullWidth
            variant="outlined"
            color="secondary"
            disabled={disabled}
            onClick={onClick}
          >
            <Typography variant="button" noWrap>
              {t(loading ? 'sharedLoading' : 'reportShow')}
            </Typography>
          </Button>
        ) : (
          <SplitButton
            fullWidth
            variant="outlined"
            color="secondary"
            disabled={disabled}
            onClick={onClick}
            selected={selectedOption}
            setSelected={onSelected}
            options={options}
          />
        )}
      </div>
    </div>
  );
};

export default ReportFilter;

