44:           const last = route.at(-1);
45:           if (!last || last[0] !== position.longitude || last[1] !== position.latitude) {
46:             state.history[position.deviceId] = [
47:               ...route.slice(1 - liveRoutesLimit),
48:               [position.longitude, position.latitude],
49:             ];
50:           }
